ALTER TABLE products ADD COLUMN sections TEXT NOT NULL DEFAULT '[]';
UPDATE products SET sections = '[{"title": "Somn liniștit, fără teamă de întuneric", "image": "/img/lampa-capybara-5.jpg", "text": "Mulți copii adorm greu în întuneric complet. O lumină caldă și slabă lângă pat îi liniștește și îi ajută să adoarmă singuri.\n\nPornești temporizatorul, iar lampa se stinge singură după ce cel mic a adormit. Nu mai intri în vârful picioarelor în cameră ca să stingi lumina."}, {"title": "Moale ca o jucărie", "image": "/img/lampa-capybara-6.jpg", "text": "E făcută din silicon moale, plăcut la atingere. Copilul o poate ține în brațe, o poate lua în pat și nu se sparge dacă îi scapă pe jos.\n\nNu are muchii tăioase și nici piese de sticlă."}, {"title": "Lumina exact cât îți trebuie", "image": "/img/lampa-capybara-3.jpg", "text": "Atingi lampa și alegi intensitatea: o lumină slabă pentru somn sau una mai puternică pentru joacă și poveștile de seară.\n\nSe încarcă prin cablul USB inclus, așa că o pui oriunde, fără prelungitoare și fără cablu în priză toată noaptea."}, {"title": "Frumoasă și ziua, pe raft", "image": "/img/lampa-capybara-7.jpg", "text": "Are 14 × 8 cm, încape pe noptieră, pe birou sau pe raftul cu cărți. Chiar și stinsă, arată ca un personaj drăguț care face camera mai veselă."}, {"title": "Un cadou pe care îl folosesc în fiecare seară", "image": "/img/lampa-capybara-8.jpg", "text": "Pentru copii, dar și pentru adolescenți și adulți care vor o lumină caldă pe birou sau lângă pat.\n\nVine într-o cutie de prezentare, gata de oferit, împreună cu cablul USB și instrucțiunile."}]', images = '["/img/lampa-capybara-1.jpg", "/img/lampa-capybara-2.jpg", "/img/lampa-capybara-3.jpg", "/img/lampa-capybara-4.jpg", "/img/lampa-capybara-6.jpg", "/img/lampa-capybara-5.jpg"]' WHERE slug = 'lampa-de-veghe-capybara';
